-- main.sql : red, sismo y probabilidades de falla de cada enlace tras el sismo M8.8 (USGS official20100227063411530_30)
-- Generado 2026-11-19 16:05 por scripts/modelo_falla.py  (fuente=circular, K=1.0)
-- Modelo: ruptura circular Strasser 2010 (R = 159.3 km) -> Youngs 1997 (PGA) -> Wald 1999 (MMI, PGV) -> ALA 2001 (RR) -> Poisson
-- Autocontenido: se puede cargar en una base vacia con  psql -v ON_ERROR_STOP=1 -f main.sql

SET client_min_messages = warning;
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pgrouting;
CREATE SCHEMA IF NOT EXISTS red;
CREATE SCHEMA IF NOT EXISTS sismo;
DROP TABLE IF EXISTS red.prob_falla, red.nodos_clave, red.aristas, red.aristas_vertices_pgr, sismo.evento, sismo.zonas CASCADE;

-- 1) Red (topologia de pgr_createTopology), nodos clave, sismo y zonas

-- red.nodos_clave
CREATE TABLE red.nodos_clave(
  "id" integer,
  "nombre" text,
  "region" text,
  "rol" text[],
  "geom" geometry(Point,4326),
  "vertice_id" integer,
  "dist_a_red_km" numeric,
  "vertice_fibra" integer,
  "dist_a_fibra_km" numeric,
  PRIMARY KEY (id));

-- red.aristas
CREATE TABLE red.aristas(
  "id" bigint,
  "capa" text,
  "tipo" text,
  "longitud_m" double precision,
  "geom" geometry(LineString,4326),
  "source" integer,
  "target" integer,
  "p_falla" double precision,
  PRIMARY KEY (id));
CREATE INDEX ON red.aristas USING gist(geom);
CREATE INDEX ON red.aristas (source);
CREATE INDEX ON red.aristas (target);

-- red.aristas_vertices_pgr
CREATE TABLE red.aristas_vertices_pgr(
  "id" bigint,
  "cnt" integer,
  "chk" integer,
  "ein" integer,
  "eout" integer,
  "the_geom" geometry(Point,4326),
  PRIMARY KEY (id));
CREATE INDEX ON red.aristas_vertices_pgr USING gist(the_geom);

-- sismo.evento
CREATE TABLE sismo.evento(
  "id_usgs" text,
  "titulo" text,
  "magnitud" numeric(3,1),
  "tipo_magnitud" text,
  "fecha_utc" timestamp with time zone,
  "prof_km" numeric,
  "mmi_usgs" numeric,
  "cdi_usgs" numeric,
  "reportes_sentido" integer,
  "url" text,
  "propiedades" jsonb,
  "geom" geometry(Point,4326),
  PRIMARY KEY (id_usgs));

-- sismo.zonas
CREATE TABLE sismo.zonas(
  "tipo" text,
  "descripcion" text,
  "radio_km" numeric,
  "area_km2" numeric,
  "geom" geometry(Polygon,4326),
  PRIMARY KEY (tipo));

-- 2) Probabilidad de falla de cada enlace
CREATE TABLE red.prob_falla(
  arista_id int PRIMARY KEY, capa text, longitud_m double precision,
  dist_fuente_km double precision, pga_g double precision, mmi double precision,
  pgv_cm_s double precision, tasa_reparacion_km double precision, p_falla double precision);
ANALYZE red.aristas;
